import sys
sys.path.insert(0,'/app/output')
import gen
import numpy as np
from PIL import Image
from scipy.ndimage import gaussian_filter,sobel
plan,_=gen.make_plan(); gen.save_preview(plan)
src=np.asarray(Image.open('/app/target.png').convert('RGB'),float)
target=gen.rgb_to_lab(gaussian_filter(src,(4.5,4.5,0)))
pal=gen.PALETTE_LAB

def runs(labline,minlen):
 labels=np.linalg.norm(labline[:,None,:]-pal[None,:,:],axis=2).argmin(1)
 return gen.merge_short_runs(labels,minlen)
def stats(out):
 outlab=gen.rgb_to_lab(gaussian_filter(out.astype(float),(4.5,4.5,0)))
 de=np.linalg.norm(target-outlab,axis=-1)[36:-36,36:-36]
 Lt,Lo=target[:,:,0],outlab[:,:,0]
 def ss(a,b,sig):
  mu1=gaussian_filter(a,sig);mu2=gaussian_filter(b,sig);s1=gaussian_filter(a*a,sig)-mu1**2;s2=gaussian_filter(b*b,sig)-mu2**2;cov=gaussian_filter(a*b,sig)-mu1*mu2
  return ((2*mu1*mu2+6.5025)*(2*cov+58.5225)/((mu1**2+mu2**2+6.5025)*(s1+s2+58.5225)))
 ssimi=ss(Lt,Lo,6.75)[36:-36,36:-36].mean()
 g1=np.hypot(sobel(Lt,0),sobel(Lt,1));g2=np.hypot(sobel(Lo,0),sobel(Lo,1))
 ec=np.corrcoef(g1[36:-36,36:-36].ravel(),g2[36:-36,36:-36].ravel())[0,1]
 return np.round([de.mean(),np.percentile(de,90),ssimi,ec],3)

def render(vertical):
 out=np.full((1024,1024,3),225,dtype=np.uint8)
 tasks=[]
 for s in plan: tasks.append((s.paint,'h',s.v,s.u0,s.u1))
 for u,v0,v1,pid in vertical: tasks.append((pid,'v',u,v0,v1))
 for pid in range(1,17):
  for task in tasks:
   if task[0]!=pid: continue
   _,typ,pos,a,b=task
   if typ=='h': out[max(0,pos-23):min(1024,pos+23),a:b]=gen.PAINT_RGB[pid-1]
   else: out[a:b,max(0,pos-23):min(1024,pos+23)]=gen.PAINT_RGB[pid-1]
 return out
base=stats(render([]));print('base tasks',len(plan),base)
best=[]
# try sets of regularly spaced vertical bands; merged runs are >= 16px
for minlen in [16,20,24,28,32,36,40,48]:
 for interval in range(75,181,5):
  for offset in range(0,interval,10):
   cols=list(range(offset+interval//2,1024,interval))
   vert=[]
   for u in cols:
    band=target[:,max(0,u-23):min(1024,u+23)].mean(axis=1)
    for a,b,pid in runs(band,minlen):
     if b-a>=4: vert.append((u,a,b,pid+1))
   if len(vert)>83 or len(vert)==0: continue
   met=stats(render(vert))
   # weighted objective focus metrics currently constrained; lower DE, higher edge
   obj=met[0]+.25*max(0,10.9-met[0])+.04*max(0,20-met[1]) # retain info
   if met[0]<=10.9 and met[1]<=20 and met[2]>=.5 and met[3]>=.27:
    best.append((float(met[0]),float(met[1]),float(met[2]),float(met[3]),len(vert),interval,offset,minlen,cols,vert))
for x in sorted(best,key=lambda x:(x[0]+.4*(.5-x[2]) if x[2]<.5 else x[0]-.5*(x[3]-.27), x[1]))[:10]:
 print(x[:9])
 if x is sorted(best,key=lambda x:(x[0]+.4*(.5-x[2]) if x[2]<.5 else x[0]-.5*(x[3]-.27), x[1]))[0]: Image.fromarray(render(x[-1])).save('/app/output/stripe_plus_vertical.png')
